    constructor(uri, relativePath, context, element = undefined, parent = undefined) {
        this.uri = uri;
        this.relativePath = relativePath;
        this.context = context;
        this.element = element;
        this.parent = parent;
        this.a = new Map();
    }
    get(path) {
        return this.a.get(path);
    }
    set(path, child) {
        this.a.set(path, child);
    }
